package com.hashem.sms;
import android.app.*;import android.app.role.RoleManager;import android.telephony.SmsManager;import android.os.*;import android.content.*;import android.content.pm.PackageManager;import android.provider.Settings;import android.provider.Telephony;import android.view.*;import android.view.inputmethod.InputMethodManager;import android.widget.*;import android.graphics.Color;import android.net.Uri;import java.io.*;import java.util.*;

public class MainActivity extends Activity{
 LinearLayout root,list; EditText search; Db db; int purple=Color.rgb(103,80,164); TextView title; String filter="all";
 public void onCreate(Bundle b){super.onCreate(b);db=new Db(this);build();requestPermissionsIfNeeded();}
 TextView tv(String s,int sp){TextView t=new TextView(this);t.setText(s);t.setTextSize(sp);t.setTextColor(Color.rgb(30,30,30));t.setPadding(24,20,24,20);return t;}
 void build(){root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(Color.rgb(255,251,254));
  LinearLayout bar=new LinearLayout(this);bar.setGravity(Gravity.CENTER_VERTICAL);title=tv("هاشم SMS",24);bar.addView(title,new LinearLayout.LayoutParams(0,-2,1));Button def=new Button(this);def.setText("تطبيق SMS الافتراضي");def.setOnClickListener(v->requestDefault());bar.addView(def);root.addView(bar);
  search=new EditText(this);search.setHint("بحث في المحادثات والأرقام...");search.setSingleLine();search.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int d){}public void onTextChanged(CharSequence s,int a,int b,int c){render();}public void afterTextChanged(android.text.Editable e){}});root.addView(search);
  LinearLayout tabs=new LinearLayout(this);String[] ts={"الكل","غير مقروءة","لم ترسل","مؤرشفة","المحظورة","المهملة","جماعية","مجموعات"};String[] fs={"all","unread","failed","archived","blocked","trash","bulk","groups"};for(int i=0;i<ts.length;i++){Button x=new Button(this);x.setText(ts[i]);final String f=fs[i];x.setOnClickListener(v->{filter=f;render();});tabs.addView(x,new LinearLayout.LayoutParams(0,-2,1));}ScrollView sv=new ScrollView(this);sv.addView(tabs);root.addView(sv,new LinearLayout.LayoutParams(-1,70));
  Button compose=new Button(this);compose.setText("＋ رسالة جديدة");compose.setOnClickListener(v->composeDialog());root.addView(compose);list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);ScrollView ls=new ScrollView(this);ls.addView(list);root.addView(ls,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);render();}
 void render(){list.removeAllViews();if("bulk".equals(filter)){bulkScreen();return;}if("groups".equals(filter)){groupsScreen();return;}android.database.Cursor c=db.list(filter);String q=search.getText().toString().trim();int n=0;while(c.moveToNext()){String a=c.getString(c.getColumnIndexOrThrow("address")),body=c.getString(c.getColumnIndexOrThrow("body")),st=c.getString(c.getColumnIndexOrThrow("status"));if(!q.isEmpty()&&!a.contains(q)&&!body.contains(q))continue;LinearLayout row=new LinearLayout(this);row.setOrientation(LinearLayout.VERTICAL);TextView a1=tv(a+"   "+st,18);TextView b=tv(body,16);row.addView(a1);row.addView(b);row.setOnClickListener(v->{ Intent i=new Intent(this,ConversationActivity.class); i.putExtra("address",a); startActivity(i); });list.addView(row);n++;}c.close();if(n==0)list.addView(tv("لا توجد رسائل في هذا القسم",18));}
 void composeDialog(){composeDialog("");} void composeDialog(String addr){LinearLayout p=new LinearLayout(this);p.setOrientation(LinearLayout.VERTICAL);EditText to=new EditText(this);to.setHint("رقم الهاتف");to.setText(addr);EditText body=new EditText(this);body.setHint("نص الرسالة");body.setMinLines(5);p.addView(to);p.addView(body);Button sched=new Button(this);sched.setText("جدولة");p.addView(sched);new AlertDialog.Builder(this).setTitle("رسالة جديدة").setView(p).setPositiveButton("إرسال",(d,w)->send(to.getText().toString(),body.getText().toString())).setNegativeButton("إلغاء",null).create().show();sched.setOnClickListener(v->schedule(to.getText().toString(),body.getText().toString()));}
 void send(String a,String b){if(a.trim().isEmpty()||b.isEmpty())return;long id=db.addMessage(a,b,"out","sending");SmsManager sm=SmsManager.getDefault();ArrayList<String> parts=sm.divideMessage(b);ArrayList<PendingIntent> sent=new ArrayList<>(),del=new ArrayList<>();for(int i=0;i<parts.size();i++){Intent si=new Intent(this,SentReceiver.class);si.putExtra("id",id);Intent di=new Intent(this,DeliveredReceiver.class);di.putExtra("id",id);sent.add(PendingIntent.getBroadcast(this,1000+i,si,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE));del.add(PendingIntent.getBroadcast(this,2000+i,di,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE));}sm.sendMultipartTextMessage(a,null,parts,sent,del);render();}
 void schedule(String a,String b){long when=System.currentTimeMillis()+60000;new AlertDialog.Builder(this).setTitle("جدولة الرسالة").setMessage("سيتم الإرسال بعد دقيقة واحدة للتجربة. يمكنك تغييرها لاحقًا في قاعدة البيانات/الكود.").setPositiveButton("جدولة",(d,w)->{AlarmManager am=(AlarmManager)getSystemService(ALARM_SERVICE);Intent i=new Intent(this,ScheduleReceiver.class);i.putExtra("address",a);i.putExtra("body",b);PendingIntent pi=PendingIntent.getBroadcast(this,(int)(System.currentTimeMillis()%100000),i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);am.set(AlarmManager.RTC_WAKEUP,when,pi);db.addMessage(a,b,"out","scheduled");render();}).setNegativeButton("إلغاء",null).show();}
 void bulkScreen(){list.addView(tv("الرسائل الجماعية",24));Button imp=new Button(this);imp.setText("استيراد TXT / CSV");imp.setOnClickListener(v->importFile());list.addView(imp);EditText nums=new EditText(this);nums.setHint("الأرقام، رقم لكل سطر");nums.setMinLines(6);list.addView(nums);EditText body=new EditText(this);body.setHint("الرسالة — استخدم {name}");body.setMinLines(5);list.addView(body);Button send=new Button(this);send.setText("إرسال للجميع");send.setOnClickListener(v->{String[] ns=nums.getText().toString().split("\\s*[,;\\n]\\s*");for(String x:ns)if(!x.trim().isEmpty())send(x.trim(),body.getText().toString().replace("{name}",""));});list.addView(send);}
 void groupsScreen(){list.addView(tv("المجموعات",24));Button add=new Button(this);add.setText("إنشاء مجموعة");add.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("اسم المجموعة").setView(new EditText(this)).setPositiveButton("حفظ",null).show());list.addView(add);}
 void importFile(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("text/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,44);}
 protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(r==44&&c==RESULT_OK&&d!=null){try{InputStream in=getContentResolver().openInputStream(d.getData());BufferedReader br=new BufferedReader(new InputStreamReader(in));StringBuilder s=new StringBuilder();String line;while((line=br.readLine())!=null)s.append(line).append('\n');br.close();search.setText("");render();Toast.makeText(this,"تم استيراد النص؛ انسخه إلى حقل الأرقام",Toast.LENGTH_LONG).show();}catch(Exception e){Toast.makeText(this,e.toString(),Toast.LENGTH_LONG).show();}}}
 void requestPermissionsIfNeeded(){if(Build.VERSION.SDK_INT>=23)requestPermissions(new String[]{"android.permission.SEND_SMS","android.permission.RECEIVE_SMS","android.permission.READ_SMS","android.permission.READ_CONTACTS"},5);}
 void requestDefault(){if(Build.VERSION.SDK_INT>=29){RoleManager rm=(RoleManager)getSystemService(ROLE_SERVICE);if(rm!=null&&rm.isRoleAvailable(RoleManager.ROLE_SMS)&&!rm.isRoleHeld(RoleManager.ROLE_SMS))startActivityForResult(rm.createRequestRoleIntent(RoleManager.ROLE_SMS),99);}else{Intent i=new Intent(Telephony.Sms.Intents.ACTION_CHANGE_DEFAULT);i.putExtra(Telephony.Sms.Intents.EXTRA_PACKAGE_NAME,getPackageName());startActivity(i);}}
}
